old:
if kind.category() != last_category.as_str() {
    if !last_category.is_empty() {
        ui.separator();
    }
    last_category = kind.category().to_owned();
    ui.strong(&last_category);
}

new:
if !session.is_animation_graph()
    && kind.category() != last_category.as_str()
{
    if !last_category.is_empty() {
        ui.separator();
    }
    last_category = kind.category().to_owned();
    ui.strong(&last_category);
}
